```cpp
#include <cstdint>

// Assemble the value BY VALUE from its bytes — endian-agnostic ("Byte Order Fallacy").
uint32_t load_be32(const uint8_t* p) {
    // p[0] is the MOST-significant byte for big-endian, so it occupies the top 8 bits.
    return (uint32_t(p[0]) << 24)   // most-significant byte -> bits 24..31
         | (uint32_t(p[1]) << 16)   // -> bits 16..23
         | (uint32_t(p[2]) << 8)    // -> bits 8..15
         |  uint32_t(p[3]);         // least-significant byte -> bits 0..7
    // Each cast to uint32_t BEFORE shifting avoids shifting a promoted int by 24
    // (well-defined here, but the cast makes intent explicit and width-correct).
    // No reinterpret_cast: that would be an alignment + strict-aliasing bug.
}
```

