#include <bit>
#include <cstdint>

// (a) Portable: loops once per SET bit. Kernighan's trick `x &= x - 1` clears the
// lowest set bit each iteration, so the loop runs popcount(x) times (not 32 times).
int count_set_bits_loop(uint32_t x) {
    int n = 0;
    while (x) { x &= x - 1; ++n; }   // clear lowest set bit, count it
    return n;
}

// (b) Idiomatic C++20: std::popcount is constexpr, portable, and lowers to a single
// POPCNT instruction (~3-cycle latency, fully pipelined) -- far better than the loop,
// whose cost grows with the number of set bits.
int count_set_bits(uint32_t x) {
    return std::popcount(x);
}
```

