#include <cstddef>

// Fix for the slow column-major sweep `C`: iterate ROWS in the outer loop so the inner
// loop walks contiguous memory (stride 1). Each 64-byte cache line (16 ints) is fully
// consumed before moving on, and the hardware prefetcher can run ahead. Exactly the same
// N*N additions and the same result -- only the memory access PATTERN changes.
long C_fixed(const int* a, int N) {
    long s = 0;
    for (int r = 0; r < N; ++r)        // rows outer
        for (int c = 0; c < N; ++c)    // columns inner -> a[r*N + c] strides by 1 element
            s += a[r * N + c];
    return s;
}
```

