#include <cstddef>

// Branchless rewrite of `if (data[i] >= 128) sum += data[i];`.
// The comparison becomes a MASK and the conditional add becomes pure arithmetic, so
// there is no control-flow branch for the CPU to mispredict (a win ONLY because the
// data is unpredictable; a predictable branch would be free via speculation).
long sum_above_branchless(const int* data, std::size_t n) {
    long sum = 0;
    for (std::size_t i = 0; i < n; ++i) {
        int v = data[i];
        long mask = -(long)(v >= 128);   // (v>=128) is 0 or 1; negating gives 0 or 0xFFFF...FFFF
        sum += v & mask;                 // mask all-ones keeps v; mask zero contributes 0
    }
    return sum;
    // The compiler may also lower this to a CMOV. Verify the effect with
    // `perf stat -e branches,branch-misses` on real (random) data.
}
```

