#include <atomic>
#include <cstddef>
#include <new>

// Cache-line size: prefer the C++17 constant std::hardware_destructive_interference_size
// where the standard library provides it; otherwise fall back to 64 (the line size on all
// current x86-64 and Apple-silicon cores) so this compiles everywhere.
#if defined(__cpp_lib_hardware_interference_size)
inline constexpr std::size_t kCacheLine = std::hardware_destructive_interference_size;
#else
inline constexpr std::size_t kCacheLine = 64;
#endif

// alignas forces each counter onto its OWN cache line, so a write to `a` no longer
// invalidates the line holding `b` (and vice versa). The coherence ping-pong that made
// the two cores fight over one shared line -- false sharing -- disappears.
struct Counters {
    alignas(kCacheLine) std::atomic<long> a;
    alignas(kCacheLine) std::atomic<long> b;
};
```

