#include <cstddef>

// __restrict promises the compiler that `a` and `b` never alias (point into disjoint
// memory). Without it, a store through one pointer might change a load through the other,
// so the compiler must keep the loads/stores in order -- blocking vectorization, CSE, and
// reordering. With it, those optimizations are unblocked. The math is unchanged.
float dot(const float* __restrict a, const float* __restrict b, int n) {
    float s = 0.0f;
    for (int i = 0; i < n; ++i) s += a[i] * b[i];
    return s;
    // Non-aliasing is the FIRST blocker. The summation into one float is still a
    // loop-carried FP dependency that strict IEEE rules forbid reassociating; to get
    // multiple SIMD accumulators you additionally need -ffast-math / -fassociative-math
    // or `#pragma omp simd reduction(+:s)` (at the cost of bit-exact reproducibility).
    // Compile with -O3 -march=native; check with -fopt-info-vec / -fopt-info-vec-missed.
}
