#include <unistd.h>
#include <sys/wait.h>

// Run `path` with `argv`, wait for it, return its exit code (or -1 on failure).
int run(const char* path, char* const argv[]) {
    pid_t pid = fork();
    if (pid < 0) return -1;             // fork failed
    if (pid == 0) {                     // child branch: fork() returns 0 here
        execv(path, argv);              // on success this NEVER returns (image replaced)
        _exit(127);                     // reached only if exec failed; _exit avoids
                                        // flushing the parent's inherited stdio buffers
    }
    int status = 0;                     // parent branch: fork() returned the child PID
    if (waitpid(pid, &status, 0) < 0) return -1;   // reap the child (prevents a zombie)
    if (WIFEXITED(status)) return WEXITSTATUS(status);  // normal exit -> its code
    return -1;                          // killed by a signal, etc.
}
```

