class Queue {
    std::queue<int> q_;
    std::mutex m_;
    std::condition_variable cv_;
public:
    int pop() {
        std::unique_lock<std::mutex> lock(m_);
        // The predicate-form wait is equivalent to `while (!pred()) cv_.wait(lock);`:
        // it atomically releases the mutex and blocks, defeating the LOST-wakeup race
        // (producer pushing+signalling between a manual check and the sleep), and the
        // internal loop absorbs SPURIOUS wakeups. Never use a bare `if`.
        cv_.wait(lock, [this]{ return !q_.empty(); });
        int v = q_.front();   // predicate guarantees the queue is non-empty here
        q_.pop();
        return v;             // mutex released by unique_lock's destructor
    }
    void push(int v) {
        {
            std::lock_guard<std::mutex> lock(m_);   // hold the lock while mutating the queue...
            q_.push(v);
        }                                            // ...release BEFORE notifying
        cv_.notify_one();    // wake one waiter; the predicate is already true
    }
};
