#include <arpa/inet.h>
#include <unistd.h>
#include <cstdint>

int join_multicast(const char* group, const char* iface_ip, uint16_t port) {
    int fd = ::socket(AF_INET, SOCK_DGRAM, 0);          // UDP socket
    if (fd < 0) return -1;

    int one = 1;                                        // let several consumers bind the
    if (::setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one) < 0) { ::close(fd); return -1; }
                                                        // same group:port -- set BEFORE bind

    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);           // bind all interfaces; htonl: host->net order
    addr.sin_port = htons(port);                        // ports go on the wire big-endian
    if (::bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof addr) < 0) { ::close(fd); return -1; }

    ip_mreq mreq{};
    mreq.imr_multiaddr.s_addr = ::inet_addr(group);     // the multicast group IP
    mreq.imr_interface.s_addr = ::inet_addr(iface_ip);  // WHICH NIC to receive on (critical on a
                                                        // multi-homed box: wrong iface -> silence)
    if (::setsockopt(fd, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof mreq) < 0) { ::close(fd); return -1; }

    return fd;
}
