#include <sys/socket.h>
#include <cerrno>
#include <cstddef>
#include <cstdint>

// TCP is a byte stream with NO message boundaries: one recv() may return a partial
// chunk or several sends coalesced. So we must loop until we have exactly n bytes.
bool recv_exact(int fd, void* buf, size_t n) {
    auto* p = static_cast<uint8_t*>(buf);
    size_t got = 0;
    while (got < n) {
        ssize_t r = ::recv(fd, p + got, n - got, 0);   // ask only for what's still missing
        if (r > 0) { got += static_cast<size_t>(r); continue; }  // partial read: advance & continue
        if (r == 0) return false;                 // peer performed an orderly close: EOF before n
        if (errno == EINTR) continue;             // interrupted by a signal: just retry
        return false;                             // real error (or EAGAIN/EWOULDBLOCK on a nonblocking fd)
    }
    return true;
    // Framing (length prefix or delimiter) is the caller's job; recv_exact is the
    // building block. On a non-blocking socket you would treat EAGAIN by waiting for
    // readability via epoll/kqueue instead of returning false.
}
