#include <atomic>
#include <cstddef>
#include <new>

// Cache-line size for padding: C++17 constant where available, else 64.
#if defined(__cpp_lib_hardware_interference_size)
inline constexpr std::size_t kSpscAlign = std::hardware_destructive_interference_size;
#else
inline constexpr std::size_t kSpscAlign = 64;
#endif

template <class T, std::size_t Cap>
class SpscRing {
    // Power-of-two capacity lets us index with a cheap mask `& (Cap-1)` instead of modulo,
    // and lets the monotonic indices wrap naturally.
    static_assert((Cap & (Cap - 1)) == 0, "Cap must be a power of two");

    T buffer_[Cap];
    // head_ and tail_ are padded onto SEPARATE cache lines so the producer's store to
    // head_ does not invalidate the consumer's line (and vice versa) -- no false sharing.
    alignas(kSpscAlign) std::atomic<std::size_t> head_{0};  // producer-only writer
    alignas(kSpscAlign) std::atomic<std::size_t> tail_{0};  // consumer-only writer

public:
    bool try_push(const T& v) {
        const std::size_t h = head_.load(std::memory_order_relaxed);   // we are head_'s only writer
        const std::size_t t = tail_.load(std::memory_order_acquire);   // observe consumer progress
        if (h - t == Cap) return false;                                // full (monotonic indices: never ambiguous)
        buffer_[h & (Cap - 1)] = v;                                    // write payload BEFORE publishing
        head_.store(h + 1, std::memory_order_release);                 // publish: release pairs with pop's acquire
        return true;
    }

    bool try_pop(T& out) {
        const std::size_t t = tail_.load(std::memory_order_relaxed);   // we are tail_'s only writer
        const std::size_t h = head_.load(std::memory_order_acquire);   // observe producer's publish
        if (h == t) return false;                                      // empty
        out = buffer_[t & (Cap - 1)];                                  // read the published payload
        tail_.store(t + 1, std::memory_order_release);                 // free the slot for the producer
        return true;
    }
    // Single writer per index => no CAS, no retry loop. On x86 these acquire/release ops
    // are plain MOVs, so the only real cost is cross-core cache-line coherence. Trivially
    // copyable -> works in a MAP_SHARED region for cross-process IPC. MPMC would need CAS.
};
