#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <atomic>
#include <new>
#include <cstdio>

struct Shared {
    std::atomic<int> ready;
    int value;
};

// Producer: create + size + map a POSIX shm object, construct Shared in place,
// write value, then publish with a release store on `ready`. Returns 0 / -1.
int produce(const char* name, int v) {
    int fd = ::shm_open(name, O_CREAT | O_RDWR, 0600);   // tmpfs-backed object (/dev/shm)
    if (fd < 0) return -1;
    if (::ftruncate(fd, sizeof(Shared)) < 0) { ::close(fd); return -1; }  // size BEFORE mapping (else SIGBUS)

    void* p = ::mmap(nullptr, sizeof(Shared), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    ::close(fd);                                  // the mapping outlives the fd
    if (p == MAP_FAILED) return -1;

    auto* s = ::new (p) Shared{};                 // placement-new into the shared pages
    s->value = v;                                 // write payload first
    s->ready.store(1, std::memory_order_release); // publish: release pairs with consumer's acquire

    ::munmap(p, sizeof(Shared));
    // consumer (other process) maps the same name and spins on `ready` with acquire,
    // then reads `value` (guaranteed visible). shm_unlink when done with the object.
    return 0;
}
