#include <cstdint>
#include <cstddef>

// --- Mock NIC layer (stands in for DPDK; the real APIs are rte_eth_rx_burst /
//     rte_pktmbuf_free, which need the DPDK SDK and a bound NIC -- not buildable here).
//     A "packet" is just an int payload. rx_burst() is NON-BLOCKING: it returns 0..max
//     ready packets, exactly like rte_eth_rx_burst reading the RX descriptor ring. ---
struct Mbuf { int payload; bool freed; };
struct MockNic {
    int* src; int total; int pos;
    long processed_sum; int processed_count; int freed_count;
    uint16_t rx_burst(Mbuf* out, uint16_t max) {    // returns 0..max ready packets; never blocks
        uint16_t n = 0;
        while (n < max && pos < total) { out[n].payload = src[pos++]; out[n].freed = false; ++n; }
        return n;                                    // may be 0: caller must spin, not sleep
    }
    void process(Mbuf* m) { processed_sum += m->payload; ++processed_count; }
    void pkt_free(Mbuf* m) { m->freed = true; ++freed_count; }
    bool done() const { return pos >= total; }
};

static constexpr uint16_t BURST = 32;

// Run-to-completion poll loop, mirroring a DPDK lcore: burst-receive, process each
// packet, free each buffer -- with NO syscalls and NO blocking. rx_burst()==0 just
// means "nothing ready yet", so we spin again (in real DPDK this is `for(;;)`; here we
// stop when the mock source drains so the unit test terminates).
void rx_loop(MockNic& nic) {
    Mbuf bufs[BURST];
    while (!nic.done()) {
        const uint16_t n = nic.rx_burst(bufs, BURST);   // non-blocking burst receive
        if (n == 0) continue;                           // spin again -- no sleep, no syscall
        for (uint16_t i = 0; i < n; ++i) {
            nic.process(&bufs[i]);                       // frame already DMA'd into the mbuf -> no copy
            nic.pkt_free(&bufs[i]);                      // return the buffer to the mempool
        }
    }
    // The trade-off: a core pegged at 100% even with zero traffic -- correct for HFT,
    // buying deterministic sub-microsecond, low-jitter delivery. Batching (the _burst
    // APIs) amortizes per-packet PCIe/descriptor cost. lcore+mempool+rings live on the NIC's NUMA node.
}
