#include <cstddef>
#include <cstdint>
#include <new>

// Bump-pointer (monotonic) allocator: carve aligned slices out of one fixed buffer.
// Allocation is just "align the offset, then add the size" -- no free list, no lock,
// no syscall -- so it is far cheaper than a general malloc. reset() reclaims everything
// at once (you cannot free a single object), which fits per-tick scratch memory perfectly.
class ArenaAllocator {
    std::byte* buf_;
    std::size_t cap_;
    std::size_t off_ = 0;
public:
    ArenaAllocator(std::byte* buffer, std::size_t cap) : buf_(buffer), cap_(cap) {}

    void* allocate(std::size_t bytes, std::size_t align) {
        std::uintptr_t cur = reinterpret_cast<std::uintptr_t>(buf_ + off_);    // current address
        std::uintptr_t aligned = (cur + (align - 1)) & ~(std::uintptr_t)(align - 1); // round UP (align = 2^k)
        std::size_t pad = static_cast<std::size_t>(aligned - cur);             // bytes skipped to align
        if (off_ + pad + bytes > cap_) return nullptr;                         // would overflow the arena
        off_ += pad;                                                           // consume the padding
        void* p = buf_ + off_;
        off_ += bytes;                                                         // consume the request
        return p;
    }

    void reset() { off_ = 0; }   // reclaim everything at once; no per-object free
    // This is exactly std::pmr::monotonic_buffer_resource. Combine with placement-new (or
    // pmr containers) to build objects in the bytes. Pre-fault + mlock the backing buffer
    // at startup so the hot path never takes a page fault.
};
