#include <cstdint>

// CRTP base parameterized on the concrete Derived type. run() forwards to the derived
// onTick() via static_cast resolved AT COMPILE TIME -- no vtable load, no indirect call,
// hence no branch-target misprediction, and (the big win) no inlining barrier, so
// constant propagation and vectorization can flow across the call.
template <class Derived>
struct Strategy {
    void run(int tick) {
        static_cast<Derived*>(this)->onTick(tick);  // compile-time dispatch to the derived method
    }
};

// A concrete strategy: sums the ticks it sees (stand-in for "compute a signal").
struct Momentum : Strategy<Momentum> {
    long signal = 0;
    void onTick(int tick) { signal += tick; }   // called directly; the compiler can inline it
};

// A second strategy proves dispatch is per-type and resolved statically (no shared vtable).
struct MeanReversion : Strategy<MeanReversion> {
    int count = 0;
    void onTick(int /*tick*/) { ++count; }
};
// Use static polymorphism (CRTP/templates/std::variant) on hot paths where the type is
// fixed at compile time. Reserve `virtual` for cold paths where the type set is unknown
// until runtime (plugins, config) -- the zero-overhead principle: do not pay for dynamic
// dispatch you do not need. The empty CRTP base adds zero bytes (empty base optimization).
